#!/usr/bin/env bash
# Builds what the iOS app links: packwing-mobile as a static library for
# iPhones and the Simulator (Apple silicon), wrapped in an XCFramework, and
# the Swift that calls it, generated by UniFFI.
#
#   scripts/build_ios.sh            release libraries
#   scripts/build_ios.sh --debug    quicker to build, slower to run
#
# Writes ios/Generated/PackwingCore.xcframework and
# ios/Generated/packwing_mobile.swift (neither is committed). Needs Xcode
# (not only the Command Line Tools) and the two targets:
#   rustup target add aarch64-apple-ios aarch64-apple-ios-sim
set -euo pipefail

cd "$(dirname "$0")/.."
ROOT="$PWD"
PROFILE=release
FLAG=--release
if [[ "${1:-}" == "--debug" ]]; then
	PROFILE=debug
	FLAG=
fi

export DEVELOPER_DIR="${DEVELOPER_DIR:-/Applications/Xcode.app/Contents/Developer}"
# The oldest iOS the app runs on (ios/project.yml says the same).
export IPHONEOS_DEPLOYMENT_TARGET=26.0
CARGO="${CARGO:-cargo}"
OUT="$ROOT/ios/Generated"
LIB=libpackwing_mobile.a
TARGETS=(aarch64-apple-ios aarch64-apple-ios-sim)

for t in "${TARGETS[@]}"; do
	echo "building packwing-mobile for $t ($PROFILE)"
	"$CARGO" build -p packwing-mobile --lib $FLAG --target "$t"
done

# The Swift side and the C header it calls through, read from the library's
# own metadata, so they always match what was built.
rm -rf "$OUT"
mkdir -p "$OUT/headers"
"$CARGO" run -q -p packwing-mobile --features bindgen --bin uniffi-bindgen -- \
	generate --library "target/aarch64-apple-ios-sim/$PROFILE/$LIB" \
	--language swift --out-dir "$OUT/bindings"
mv "$OUT/bindings/packwing_mobile.swift" "$OUT/"
mv "$OUT/bindings/packwing_mobileFFI.h" "$OUT/headers/"
# Clang looks for module.modulemap by that name inside the headers folder.
mv "$OUT/bindings/packwing_mobileFFI.modulemap" "$OUT/headers/module.modulemap"
rm -rf "$OUT/bindings"

xcodebuild -create-xcframework \
	-library "target/aarch64-apple-ios/$PROFILE/$LIB" -headers "$OUT/headers" \
	-library "target/aarch64-apple-ios-sim/$PROFILE/$LIB" -headers "$OUT/headers" \
	-output "$OUT/PackwingCore.xcframework" >/dev/null
rm -rf "$OUT/headers"
echo "built $OUT/PackwingCore.xcframework and $OUT/packwing_mobile.swift"
